_RE = re.compile(r"(^|[\s.,!?])(" + "|".join(sorted(map(re.escape, NIQ), key=len, reverse=True)) + r")(?=$|[\s.,!?])")
def vowel(t):
    return _RE.sub(lambda m: m.group(1) + NIQ[m.group(2)], t)

VOICES = {"hila": "he-IL-HilaNeural", "avri": "he-IL-AvriNeural"}

async def tts(text, voice, sem):
    import edge_tts
    async with sem:
        for attempt in range(4):
            try:
                data = b""
                async for chunk in edge_tts.Communicate(vowel(text), voice, rate="+5%").stream():
                    if chunk["type"] == "audio":
                        data += chunk["data"]
                if data:
                    return data
            except Exception:
                await asyncio.sleep(1 + attempt)
        raise RuntimeError("נכשל: " + text)

async def main():
    args = sys.argv[1:]
    if not args:
        print(__doc__); return
    path = args[0]
    voice = VOICES["hila"]
    if "--voice" in args:
        voice = VOICES.get(args[args.index("--voice") + 1], voice)
    html = open(path, encoding="utf-8").read()
    if "/*CLIPS*/" not in html:
        print("זה לא קובץ המשחק הנכון."); return
    sem = asyncio.Semaphore(8)
    done = 0
    async def one(t):
        nonlocal done
        b = await tts(t, voice, sem)
        done += 1
        print(f"\r{done}/{len(PHRASES)}", end="", flush=True)
        return t, "data:audio/mpeg;base64," + base64.b64encode(b).decode()
    pairs = await asyncio.gather(*[one(t) for t in PHRASES])
    clips = json.dumps(dict(pairs), ensure_ascii=False)
    html = re.sub(r"const CLIPS=\{.*?\};/\*CLIPS\*/", lambda m: "const CLIPS=" + clips + ";/*CLIPS*/", html, count=1, flags=re.S)
    out = re.sub(r"\.html$", "", path) + "-voice.html"
    open(out, "w", encoding="utf-8").write(html)
    print(f"\nמוכן! {out}  ({len(html)//1024} KB)")

asyncio.run(main())
